def find_missing(arr):
  # sort the array
  arr.sort()

  # iterate through the array to find the smallest positive integer not present 
  for i in range(len(arr)):
    if arr[i] > 0:
      if arr[i+1] != arr[i] + 1:
        return arr[i] + 1
  return arr[-1] + 1
