fn calculate_high_flossing(
    brand1: f64, 
    brand2: f64, 
    thread_type: &str, 
    user_age: usize) -> String {

    // Define variables for storing calculated scores
    let mut score1 = 0.;
    let mut score2 = 0.;

    match thread_type {
        "Waxed" => {
            score1 += 5.;
            score2 -= 3.;
        }
        "Unwaxed" | _ => {}
    };

    match user_age {
        18..=64 => {
            score1 += 2.;
            score2 += 2.;
        },
        65..=79 => {
            score1 += 3.;
        },
        _ => {
            score1 -= 3;
            score2 -= 5;
        }
    };

    // Calculate final score based on combined scores from both brands
    let total_score = (brand1 * score1 + brand2 * score2) / (score1 + score2);

    // Return result as a string
    return format!("The high flossing value for '{}' thread type and age group is {:.2}", 
        thread_type, total_score);

}
```
