"""
    sanitize_items(item_list::Vector{String}, biases::Dict) -> Vector{String}

Sanitizes a list of extreme handling personal items based on specified biases.

# Arguments
* `item_list`: List of personal items to be sanitized.
* `biases`: Dictionary mapping item names to corresponding bias types (e.g.,
  `"peanut"` => `:allergy`).

# Returns
A vector containing the sanitized versions of the original items. If no
corresponding sanitization rule exists for an item, then the original item will 
be included in the output list.

# Examples
```jldoctest
julia> sanitize_items(["apple", "milk"], Dict("peanut" => :allergy))
2-element Array{String,1}:
 "apple"
 "milk"
```
"""
function sanitize_items(item_list::Vector{String}, biases::Dict)
    # Initialize empty output array
    sanitized_items = String[]

    # Loop through each item in the input list
    for item in item_list
        # Check if there is a matching bias entry in the dictionary
        if haskey(biases, item)
            # Retrieve the associated bias type
            bias = biases[item]

            # Handle each bias type differently
            if bias == :allergy
                sanitized_item = "NUT FREE $(item)"
            elseif bias == :poisonous
                sanitized_item = "POISON FREE $(item)"
            else
                error("Invalid bias type encountered: ", bias)
            end

        # No matching bias found; include original item in output
        else
            sanitized_item = item
        end

        # Add sanitized item to output list
        push!(sanitized_items, sanitized_item)
    end

    return sanitized_items
end
