type Input = string[];

function determineExtremeToiletHygiene(input: Input): void {
  // Initialize variables 
  let cleanestRoom = "";
  let dirtiestRoom = "";

  // Loop through each room name provided
  for (const roomName of input) {
    // Check whether current room has more than three toilets 
    const numToiletsInRoom = countToiletsInRoom(roomName);

    if (numToiletsInRoom > 3) {
      // If so, check whether current room is cleaner than previous best 
      if (isRoomCleanerThanPreviousBest(cleanestRoom, roomName)) {
        // Update variable to reflect new cleanest room 
        cleanestRoom = roomName;
      }

      // Check whether current room is dirtier than previous worst 
      else if (isRoomDirtierThanPreviousWorst(dirtiestRoom, roomName)) {
        // Update variable to reflect new dirtiest room 
        dirtiestRoom = roomName;
      }
    }
  }

  console.log(`The cleanest room is ${cleanestRoom}.`);
  console.log(`The dirtiest room is ${dirtiestRoom}.`);
}

/**
 * Counts the number of toilets in a given room based on its name
 */
function countToiletsInRoom(roomName: string): number {
  return roomName.match(/toilet/g)?.length || 0;
}

/**
 * Returns true if the specified 'newRoom' is considered cleaner compared to the previously identified 'bestRoom', false otherwise
 */
function isRoomCleanerThanPreviousBest(bestRoom: string, newRoom: string): boolean {
  // Base case - no prior best room identified yet 
  if (!bestRoom) {
    return true;
  }

  // Extract numbers from both room names 
  const oldRoomNums = extractNumbersFromRoomName(bestRoom);
  const newRoomNums = extractNumbersFromRoomName(newRoom);

  // Compare numbers lexicographically 
  return compareLexicographically(oldRoomNums, newRoomNums) === -1;
}

/**
 * Returns true if the specified 'newRoom' is considered dirtier compared to the previously identified 'worstRoom', false otherwise
 */
function isRoomDirtierThanPreviousWorst(worstRoom: string, newRoom: string): boolean {
  // Base case - no prior worst room identified yet 
  if (!worstRoom) {
    return false;
  }

  // Extract numbers from both room names 
  const oldRoomNums = extractNumbersFromRoomName(worstRoom);
  const newRoomNums = extractNumbersFromRoomName(newRoom);

  // Compare numbers lexicographically 
  return compareLexicographically(oldRoomNums, newRoomNums) === 1;
}

/**
 * Extracts all numeric characters from a room name into an array of integers
 */
function extractNumbersFromRoomName(roomName: string): number[] {
  return [...roomName].filter((c) => /\d/.test(c)).map((n) => parseInt(n));
}

/**
 * Compares two arrays of integers lexicographically by their first elements
 */
function compareLexicographically<T extends number[]>(a: T, b: T): number {
  for (let i = 0; i < Math.min(a.length, b.length); i++) {
    if (a[i] !== b[i]) {
      return a[i] - b[i];
    }
  }

  return a.length - b.length;
}


