Develop a Python Flask web application that provides a RESTful API for managing a simple task list, supporting CRUD operations on tasks (with properties like title, description, due date, and status). Use SQLite as the backend database.
PLAINFORMAT


from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
import os

# Initialize Flask app
app = Flask(__name__)

# Configure SQLite database
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///tasks.db'
db = SQLAlchemy(app)

class Task(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text, nullable=True)
    due_date = db.Column(db.String(10), nullable=True)
    status = db.Column(db.String(20), nullable=False, default='pending')

    def __repr__(self):
        return f'<Task {self.title}>'

if not os.path.exists('tasks.db'):
    db.create_all()

@app.route('/')
def index():
    return "Welcome to the Task Manager!"

# Get all tasks
@app.route('/tasks', methods=['GET'])
def get_tasks():
    tasks = Task.query.all()
    return jsonify([task.to_dict() for task in tasks])

# Get a specific task by ID
@app.route('/tasks/<int:task_id>', methods=['GET'])
def get_task(task_id):
    task = Task.query.get_or_404(task_id)
    return jsonify(task.to_dict())

# Create a new task
@app.route('/tasks', methods=['POST'])
def create_task():
    data = request.get_json()
    title = data['title']
    description = data.get('description')
